import React, { createContext, useContext, useState, useRef } from 'react';
import { DUMMY_USERS, DUMMY_RESOURCES } from '../data/dummyData';

const AppContext = createContext();

export function AppProvider({ children }) {

  // ── State ──────────────────────────────────────────────────
  const [page, setPage]                   = useState('landing');
  const [user, setUser]                   = useState(null);
  const [dark, setDark]                   = useState(true);
  const [toasts, setToasts]               = useState([]);
  const [selectedCollege, setSelectedCollege] = useState(null);
  const [resources, setResources]         = useState(DUMMY_RESOURCES);
  const [users, setUsers]                 = useState(DUMMY_USERS);
  const [routineDone, setRoutineDone]     = useState({});
  const toastId = useRef(0);

  // ── Toast helper — defined FIRST so everything below can use it ──
  const toast = (msg, type = 'success') => {
    const id = ++toastId.current;
    setToasts((prev) => [...prev, { id, msg, type }]);
    setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 3500);
  };

  const removeToast = (id) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  };

  // ── Auth ───────────────────────────────────────────────────
  const login = (email, password) => {
    const found = users.find(
      (u) => u.email === email && u.password === password
    );
    if (!found) {
      toast('Invalid email or password. Please try again.', 'error');
      return false;
    }
    setUser(found);
    setPage('dashboard');
    toast(`Welcome back, ${found.name.split(' ')[0]}! 👋`);
    return true;
  };

  const register = (data) => {
    const exists = users.find((u) => u.email === data.email);
    if (exists) {
      toast('Email already registered', 'error');
      return false;
    }
    const newUser = {
      ...data,
      id: users.length + 1,
      avatar: data.name
        .split(' ')
        .map((n) => n[0])
        .join('')
        .slice(0, 2)
        .toUpperCase(),
      joinDate: new Date().toISOString().slice(0, 10),
    };
    setUsers((prev) => [...prev, newUser]);
    setUser(newUser);
    setPage('dashboard');
    toast(`Account created! Welcome, ${data.name.split(' ')[0]}! 🎉`);
    return true;
  };

  const logout = () => {
    setUser(null);
    setPage('landing');
    setSelectedCollege(null);
    toast('Logged out successfully');
  };

  // ── Resources ──────────────────────────────────────────────
  const addResource = (res) => {
    setResources((prev) => [
      ...prev,
      {
        ...res,
        id:         prev.length + 1,
        date:       new Date().toISOString().slice(0, 10),
        downloads:  0,
        views:      0,
        registered: 0,
      },
    ]);
    toast('Resource uploaded successfully! 📚');
  };

  // ── Users (admin) ──────────────────────────────────────────
  const removeUser = (id) => {
    setUsers((prev) => prev.filter((u) => u.id !== id));
    toast('User removed', 'warning');
  };

  // ── Context value ──────────────────────────────────────────
  const value = {
    page,
    setPage,
    user,
    dark,
    setDark,
    toast,
    toasts,
    removeToast,
    login,
    register,
    logout,
    selectedCollege,
    setSelectedCollege,
    resources,
    addResource,
    users,
    setUsers,
    removeUser,
    routineDone,
    setRoutineDone,
  };

  return (
    <AppContext.Provider value={value}>
      {children}
    </AppContext.Provider>
  );
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used inside AppProvider');
  return ctx;
}
